import { execFile } from 'node:child_process';
import { stat } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';

const exec = promisify(execFile);
const roots = [
  'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall',
  'HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall',
  'HKLM\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall',
];

const appxCommand = "Get-AppxPackage -Name 'OpenAI.Codex' | Where-Object { $_.Name -eq 'OpenAI.Codex' } | Select-Object -ExpandProperty InstallLocation | ConvertTo-Json -Compress";

// Desktop presence is supplementary: its private codex executable is not an
// independently installed CLI. Share scans across focus/recheck requests.
export function createAgentDesktopDetector({
  platform = process.platform,
  env = process.env,
  execute = exec,
  statFile = stat,
  now = Date.now,
  ttlMs = 15_000,
} = {}) {
  const paths = platform === 'win32' ? path.win32 : path.posix;
  const value = name => Object.entries(env).find(([key]) => key.toLowerCase() === name.toLowerCase())?.[1];
  const fileExists = async filename => {
    if (!filename || !paths.isAbsolute(filename) || /[\r\n\0]/.test(filename)) return false;
    try { return (await statFile(filename)).isFile(); }
    catch { return false; }
  };
  const desktopExecutable = async filename => {
    if (!await fileExists(filename)) return false;
    const directory = paths.dirname(filename);
    // A standalone codex.exe has the same filename. Require desktop resources
    // for locations that did not come from the exact Windows package identity.
    if (await fileExists(paths.join(directory, 'resources', 'app.asar'))) return true;
    return await fileExists(paths.join(directory, 'resources.pak')) &&
      await fileExists(paths.join(directory, 'icudtl.dat'));
  };
  async function registryDesktops(detected) {
    const systemRoot = value('SystemRoot') ?? value('WINDIR') ?? 'C:\\Windows';
    const executable = paths.join(systemRoot, 'System32', 'reg.exe');
    const results = await Promise.all(roots.map(root => execute(executable, ['query', root, '/s'], {
      windowsHide: true, timeout: 10_000, maxBuffer: 16 * 1024 * 1024,
    }).then(result => result.stdout, () => '')));
    for (const output of results) {
      for (const entry of output.split(/\r?\n(?=HKEY_)/i)) {
        const field = name => new RegExp('^\\s*' + name + '\\s+REG_\\w+\\s+(.+?)\\s*$', 'im').exec(entry)?.[1];
        const name = field('DisplayName') ?? '';
        const id = /^workbuddy(?:\s|$)/i.test(name) ? 'workbuddy'
          : /^deepseek harness(?:\s|$)/i.test(name) ? 'deepseek-harness'
          : /^(?:OpenAI\s+)?Codex(?:\s+Desktop)?$/i.test(name) ? 'codex' : null;
        if (!id || detected[id]) continue;
        const executableName = id === 'workbuddy' ? 'WorkBuddy.exe' : id === 'codex' ? 'Codex.exe' : 'DeepSeek Harness.exe';
        const icon = field('DisplayIcon')?.replace(/,\s*-?\d+\s*$/, '').replace(/^"|"$/g, '');
        const location = field('InstallLocation')?.replace(/^"|"$/g, '');
        for (const file of [icon, location && paths.join(location, executableName)]) {
          if (!file || paths.basename(file).toLowerCase() !== executableName.toLowerCase()) continue;
          if (await (id === 'codex' ? desktopExecutable(file) : fileExists(file))) {
            detected[id] = true;
            break;
          }
        }
      }
    }
  }
  async function packagedCodex() {
    const systemRoot = value('SystemRoot') ?? value('WINDIR') ?? 'C:\\Windows';
    const powershell = paths.join(systemRoot, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe');
    try {
      const result = await execute(powershell, ['-NoLogo', '-NoProfile', '-NonInteractive', '-Command', appxCommand], {
        windowsHide: true, timeout: 5_000, maxBuffer: 256 * 1024,
      });
      const locations = JSON.parse(result.stdout.replace(/^\uFEFF/, '').trim() || '[]');
      for (const location of Array.isArray(locations) ? locations : [locations]) {
        if (typeof location !== 'string' || !paths.isAbsolute(location)) continue;
        if (await fileExists(paths.join(location, 'app', 'Codex.exe'))) return true;
      }
    } catch { /* Store package query may be unavailable; try verified desktop paths. */ }
    return false;
  }
  async function conventionalCodex() {
    const home = value(platform === 'win32' ? 'USERPROFILE' : 'HOME') ?? os.homedir();
    if (platform === 'darwin') {
      for (const application of ['/Applications/Codex.app', paths.join(home, 'Applications', 'Codex.app')]) {
        if (await fileExists(paths.join(application, 'Contents', 'Info.plist')) &&
            await fileExists(paths.join(application, 'Contents', 'MacOS', 'Codex'))) return true;
      }
      return false;
    }
    const candidates = platform === 'win32'
      ? [
          ...[value('LOCALAPPDATA')].filter(Boolean).flatMap(local => [
            paths.join(local, 'Programs', 'Codex', 'Codex.exe'),
            paths.join(local, 'Programs', 'OpenAI', 'Codex', 'Codex.exe'),
            paths.join(local, 'OpenAI', 'Codex', 'Codex.exe'),
            paths.join(local, 'Codex', 'Codex.exe'),
          ]),
          ...[value('ProgramFiles'), value('ProgramFiles(x86)')].filter(Boolean).flatMap(programs => [
            paths.join(programs, 'Codex', 'Codex.exe'),
            paths.join(programs, 'OpenAI', 'Codex', 'Codex.exe'),
          ]),
        ]
      : ['/opt/Codex/codex', '/opt/codex/codex', '/usr/lib/codex/codex', paths.join(home, '.local', 'share', 'Codex', 'codex')];
    for (const filename of candidates) {
      if (await desktopExecutable(filename)) return true;
    }
    return false;
  }
  async function scan() {
    const detected = { workbuddy: false, 'deepseek-harness': false, codex: false };
    const [packaged, conventional] = await Promise.all([
      platform === 'win32' ? packagedCodex() : false,
      conventionalCodex(),
      platform === 'win32' ? registryDesktops(detected) : undefined,
    ]);
    detected.codex ||= packaged || conventional;
    return detected;
  }
  let cached;
  let cachedAt = -Infinity;
  let pending;
  return async function detect() {
    if (cached && now() - cachedAt < ttlMs) return { ...cached };
    pending ??= scan().then(result => {
      cached = result;
      cachedAt = now();
      return result;
    }).finally(() => { pending = undefined; });
    return { ...await pending };
  };
}

// Keep the public API used by the agent list and provider list unchanged.
export const detectAgentDesktops = createAgentDesktopDetector();
